import sys
from collections import deque
input = sys.stdin.readline

def solve():
	n = int(input())
	par = [-1 for _ in range(n + 2)]
	child = [[] for _ in range(n + 2)]
	degree = [0] * (n + 2)
	B = list(map(int, input().split()))
	rg = [0, n]
	for i in range(n):
		if B[i] > i + 1:
			rg[0] = max(rg[0], i + 1)
		elif B[i] < i + 1:
			rg[1] = min(rg[1], i)
		par[i + 1] = B[i]
		degree[B[i]] += 1
		child[B[i]].append(i + 1)
	root = 1
	while par[root] >= 0:
		root = par[root]
	ans = []
	q = deque([root])
	while q:
		node = q.popleft()
		if 1 <= node <= n:
			ans.append(node)
		tmp = []
		for ch in child[node]:
			if degree[ch] == 0:
				q.append(ch)
			else:
				tmp.append(ch)
		while tmp:
			q.append(tmp.pop())
	print(rg[0])
	print(*ans)
	return
for _ in range(int(input())):
	solve()
